def get_pair_arrays(idx):
    txt=records[idx]['message']['content'][0]['text']
    mi=re.search(r'Demo pair \d input \(22x22\):\n(.*?)\nDemo pair \d output',txt,re.S)
    mo=re.search(r'Demo pair \d output \(22x22\):\n(.*?)\n\nSame instance',txt,re.S)
    return np.array([[int(x) for x in line.split()] for line in mi.group(1).splitlines()]), np.array([[int(x) for x in line.split()] for line in mo.group(1).splitlines()])
def find_boxes(a,bg):
    found=[]
    for r in range(18):
      for c in range(18):
        border=a[r,c]
        # require all edge cells same border; center same nonbackground color
        center=a[r+1:r+4,c+1:c+4]
        if border==bg or len(set(center.ravel())) != 1 or center[0,0] in (bg,border): continue
        patch=a[r:r+5,c:c+5]
        edge=np.ones((5,5),bool); edge[1:4,1:4]=False
        if np.all(patch[edge]==border) and np.all(center==center[0,0]):
           found.append((r,c,int(border),int(center[0,0])))
    # unique candidates could find overlaps? remove duplicate exact same
    return sorted(set(found))
