def pack_same_border(boxes,border):
    # directional extreme, solve constraints from pairwise initial left-right order
    # items tuples r,c,b,f; only same border considered
    if border==8:
      # repeatedly find each item target as max lower bounds (right neighbor constraints are for x of right item >= x_left+5)
      # since moving left, items with blockers left constrain to >= left dest +5
      items=boxes[:]
      # generic iteration initialize c=0, then enforce pairwise order
      xs={i:0 for i in range(len(items))}
      changed=True
      while changed:
        changed=False
        for i,(ri,ci,bi,fi) in enumerate(items):
          for j,(rj,cj,bj,fj) in enumerate(items):
            if i==j or not (ri<=rj+4 and rj<=ri+4): continue
            if ci<cj: # i left of j, enforce j>=i+5
              need=xs[i]+5
              if xs[j]<need: xs[j]=need; changed=True
            elif cj<ci: # j left of i
              need=xs[j]+5
              if xs[i]<need: xs[i]=need; changed=True
      return [(r,xs[i],b,f) for i,(r,c,b,f) in enumerate(items)]
    else:
      items=boxes[:]
      xs={i:17 for i in range(len(items))}
      changed=True
      while changed:
        changed=False
        for i,(ri,ci,bi,fi) in enumerate(items):
          for j,(rj,cj,bj,fj) in enumerate(items):
            if i==j or not (ri<=rj+4 and rj<=ri+4): continue
            if ci<cj:
              max_i=xs[j]-5
              if xs[i]>max_i: xs[i]=max_i; changed=True
            elif cj<ci:
              max_j=xs[i]-5
              if xs[j]>max_j: xs[j]=max_j; changed=True
      return [(r,xs[i],b,f) for i,(r,c,b,f) in enumerate(items)]
